export function renderControlCenter(nonce: string): string {
  const safeNonce = nonce.replace(/[^A-Za-z0-9_-]/g, '');
  return CONTROL_CENTER_TEMPLATE.replaceAll('__MECORD_NONCE__', safeNonce);
}
